const resp = $input.first().json;
const rows = resp.records || [];

return rows.map((r) => {
  const company = (r.company_name || r.display_name || '').trim();
  const location = [r.city, r.state].filter(Boolean).join(', ');
  const eventType = /closure/i.test(r.layoff_type || '') ? 'shutdown' : 'layoff';
  const affected = r.employees_affected;
  const title = company + ' WARN ' + eventType + (affected ? (' -- ' + affected + ' affected') : '');
  const snippet = [location, r.industry].filter(Boolean).join(' -- ') + (affected ? (' -- ' + affected + ' employees affected') : '');
  return {
    json: {
      event_id: 'warn-' + r.id,
      published_at: r.notice_date || r.effective_date,
      title: title,
      snippet: snippet,
      source_name: 'WARN Firehose',
      source_url: r.source_url || '',
      company: company,
      location: location,
      event_type: eventType,
      employees_affected: affected || null
    }
  };
}).filter((it) => it.json.company && !/\.pdf|\(pdf\)/i.test(it.json.company));

const config = $('Config').first().json;
const items = $input.all().map(i => i.json);
const itemsById = {};
items.forEach(it => { itemsById[it.event_id] = it; });

const lines = items.map(it =>
  it.event_id + ' | ' + it.published_at + ' | ' + it.title + ' | ' + it.snippet + ' | ' + it.source_name
).join('\n');

const prompt = 'RUN_TIMESTAMP: ' + new Date().toISOString() + '\n' +
  'COMPANY_PROFILE: ' + config.companyProfile + '\n' +
  'OPEN_ROLE: ' + JSON.stringify(config.openRole) + '\n' +
  'BEGIN_UNTRUSTED_ITEMS\n' + lines + '\nEND_UNTRUSTED_ITEMS';

return [{ json: { agentPrompt: prompt, itemsById: itemsById, count: items.length } }];

const agentOut = $input.first().json.output || {};
const opportunities = agentOut.opportunities || [];
const trustedMap = $('Batch For Scanner Agent').first().json.itemsById;

const results = [];
opportunities.forEach((o) => {
  const trusted = trustedMap[o.id];
  if (!trusted) { return; } // hallucinated id, drop
  results.push({
    json: {
      id: o.id,
      category: 'warn',
      company: trusted.company || o.company,
      event_type: trusted.event_type || o.event_type,
      functions: o.functions || [],
      location: trusted.location || o.location,
      employees_affected: trusted.employees_affected || null,
      published_at: trusted.published_at,
      score: o.score,
      why: o.why,
      source_name: trusted.source_name,
      source_url: trusted.source_url || ''
    }
  });
});
return results;

const config = $('Config').first().json;
const items = $input.all().map(i => i.json);
const itemsById = {};
items.forEach(it => { itemsById[it.id] = it; });

const lines = items.map(it =>
  it.id + ' | ' + it.company + ' | ' + it.event_type + ' | ' + (it.functions || []).join(',') + ' | ' + it.location + ' | ' + it.published_at + ' | scanner_score=' + it.score + ' | scanner_why=' + it.why
).join('\n');

const prompt = 'COMPANY_PROFILE: ' + config.companyProfile + '\n' +
  'OPEN_ROLE: ' + JSON.stringify(config.openRole) + '\n' +
  'BEGIN_UNTRUSTED_CANDIDATES\n' + lines + '\nEND_UNTRUSTED_CANDIDATES';

return [{ json: { judgePrompt: prompt, itemsById: itemsById } }];

const TIER_RANK = {"S":3,"A":2,"B":1,"C":0};
const TIER_BY_RANK = ['C', 'B', 'A', 'S'];
const advocate = ($('Judge Advocate').first().json.output || {}).verdicts || [];
const skeptic = ($('Judge Skeptic').first().json.output || {}).verdicts || [];
const trustedById = $('Trust-Boundary Join').all().reduce((acc, it) => { acc[it.json.id] = it.json; return acc; }, {});

const skepticById = {};
skeptic.forEach(v => { skepticById[v.id] = v; });

function ageDaysOf(p) { if (!p) { return 999; } return Math.max(0, Math.floor((Date.now() - new Date(p).getTime()) / 86400000)); }
function ageLabelOf(d) { if (d <= 0) { return 'today'; } if (d === 1) { return '1d ago'; } return d + 'd ago'; }

// Blend advocate + skeptic. Recency is a sort tiebreaker + label only (no tier penalty).
const finals = [];
advocate.forEach((a) => {
  const trusted = trustedById[a.id];
  if (!trusted) { return; }
  const ageDays = ageDaysOf(trusted.published_at);
  const s = skepticById[a.id];
  const rankA = TIER_RANK[a.tier];
  const rankS = s ? TIER_RANK[s.tier] : rankA;
  const blended = Math.round((rankA + rankS) / 2);
  finals.push({ json: {
    id: a.id,
    company: trusted.company,
    location: trusted.location,
    employees_affected: trusted.employees_affected || null,
    event_type: trusted.event_type,
    event_age_label: ageLabelOf(ageDays),
    age_days: ageDays,
    titles: a.titles,
    tier: TIER_BY_RANK[blended],
    _rank: blended,
    _disagree: Math.abs(rankA - rankS) >= 3,
    bands: [a.openness, a.role_fit, a.product_fit, a.region_fit, a.size_fit, a.stage_fit],
    wildcard: a.wildcard, why: a.why, hook: a.hook, edge: a.edge,
    held: false, hold_reason: ''
  }});
});

finals.sort((x, y) => {
  const d = (y.json._rank || 0) - (x.json._rank || 0);
  if (d !== 0) { return d; }
  return (x.json.age_days || 0) - (y.json.age_days || 0);
});

// Show between MIN_SHOWN and MAX_SHOWN: the top MIN_SHOWN always show; between that and
// MAX_SHOWN a sharp-disagreement item is held; anything past MAX_SHOWN is held as overflow.
const MIN_SHOWN = 4, MAX_SHOWN = 10;
finals.forEach((f, idx) => {
  if (idx >= MAX_SHOWN) {
    f.json.held = true; f.json.tier = 'HELD'; f.json.hold_reason = 'beyond the top ' + MAX_SHOWN + ' this run';
  } else if (f.json._disagree && idx >= MIN_SHOWN) {
    f.json.held = true; f.json.tier = 'HELD'; f.json.hold_reason = 'judges disagreed sharply';
  }
  delete f.json._rank; delete f.json._disagree;
});

return finals;

