<body>
<div class="sheet" id="scanner-report">

<div class="masthead">
  <div>
    <div class="kick"><span data-slot="author">Your name</span> · Overnight run · <span data-slot="run-date">-</span></div>
    <h1>Overnight Talent Signals<i> ·</i></h1>
